// clueId가 속한 방 id를 찾는다 (모든 페이즈를 통틀어 검색)
function findClueRoom(clueId) {
  for (const phaseKey of Object.keys(CLUES)) {
    const rooms = CLUES[phaseKey].rooms;
    for (const room of rooms) {
      if (room.items.some((item) => item.id === clueId)) return room.id;
    }
  }
  return null;
}

